def backfill_sale_payment(apps, schema_editor):
    # لینک تخصیص‌های موجود به سند واریزشان: تطبیق بر اساس زمان ثبت (همان ثانیه)
    # در همان فاکتور؛ اگر فاکتور فقط یک سند واریز دارد همه تخصیص‌ها از آن است
    ReceiptAllocation = apps.get_model('accounting', 'ReceiptAllocation')
    SaleInvoice = apps.get_model('accounting', 'SaleInvoice')
    for inv in SaleInvoice.objects.all():
        sps = list(inv.sale_payments.order_by('created_at', 'id'))
        allocs = list(ReceiptAllocation.objects.filter(
            settlement_line__invoice=inv, sale_payment__isnull=True,
        ).order_by('created_at', 'id'))
        if not sps or not allocs:
            continue
        if len(sps) == 1:
            for a in allocs:
                a.sale_payment = sps[0]
                a.save(update_fields=['sale_payment'])
            continue
        for a in allocs:
            sp = next(
                (s for s in sps
                 if s.created_at and a.created_at
                 and abs((s.created_at - a.created_at).total_seconds()) < 2
                 and s.amount == a.amount),
                None,
            )
            if sp:
                a.sale_payment = sp
                a.save(update_fields=['sale_payment'])


